TEXT ·aff2xXorAVX512(SB), NOSPLIT, $0-24
	MOVQ dst+0(FP), AX
	MOVQ src+8(FP), BX
	MOVQ n+16(FP), CX
	CMPQ CX, $128
	JLT tail
loop:
	VMOVDQU64 0(BX), Z0
	VPXORQ 0(AX), Z0, Z0
	VMOVDQU64 Z0, 0(AX)
	VMOVDQU64 64(BX), Z1
	VPXORQ 64(AX), Z1, Z1
	VMOVDQU64 Z1, 64(AX)
	ADDQ $128, AX
	ADDQ $128, BX
	SUBQ $128, CX
	CMPQ CX, $128
	JGE loop
